import{G as e,W as t,n,rt as r}from"./chunks/framework.OKfwtFe7.js";var i=JSON.parse(`{"title":"事务脚本模式（Transaction Script）","description":"","frontmatter":{},"headers":[],"relativePath":"other/transaction-script.md","filePath":"other/transaction-script.md","lastUpdated":0}`),a={name:`other/transaction-script.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="事务脚本模式-transaction-script" tabindex="-1">事务脚本模式（Transaction Script） <a class="header-anchor" href="#事务脚本模式-transaction-script" aria-label="Permalink to “事务脚本模式（Transaction Script）”">​</a></h1><p>事务脚本把一个业务流程写成一个过程式的处理函数：读数据、按流程改、写回，每步都在一个数据库事务里。它是《企业应用架构模式》领域逻辑四式中最简单的一种 [S5]，和另外三式（领域模型、表模块、活动记录）的选择依据是流程有多少条不变式、多少分支。</p><h2 id="结构" tabindex="-1">结构 <a class="header-anchor" href="#结构" aria-label="Permalink to “结构”">​</a></h2><div class="language- line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8;" tabindex="0" dir="ltr"><code><span class="line"><span>请求 → 控制器 → 事务脚本函数</span></span>
<span class="line"><span>                   ├─ 查数据（表映射或 SQL）</span></span>
<span class="line"><span>                   ├─ 按顺序改数据、算金额、校验规则</span></span>
<span class="line"><span>                   └─ 一次提交，失败整体回滚</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>三个组成部分：</p><ol><li><strong>脚本函数</strong>：一个入口对应一个业务操作（下单、退款、对账），函数体内是线性步骤。</li><li><strong>表映射</strong>：脚本直接读写行或简单对象，不构建对象图，见<a href="/hello-design-patterns/other/orm">ORM</a>。</li><li><strong>事务边界</strong>：函数开头开事务，结尾提交，异常回滚。</li></ol><h2 id="适用与不适用" tabindex="-1">适用与不适用 <a class="header-anchor" href="#适用与不适用" aria-label="Permalink to “适用与不适用”">​</a></h2><p><strong>适用</strong>（[S5] 的判据与实践一致）：</p><ul><li>流程是线性的，规则随流程走，没有对象之间来回协商；</li><li>操作基本一一对应数据库表，读改写的顺序与表结构吻合；</li><li>每个操作独立，彼此不共享复杂的中间状态。</li></ul><p><strong>不适用</strong>：</p><ul><li>规则在多个操作之间重复出现（&quot;金额不能为负&quot;在下单、退款、改价里各写一遍）——这是<a href="/hello-design-patterns/anti-patterns/anemic-domain-model">贫血模型</a>的起点；</li><li>对象之间有协作（订单要通知库存、扣券、记账），流程越写越长，滑向<a href="/hello-design-patterns/anti-patterns/spaghetti-code">意面代码</a>；</li><li>需要回放、审计单条变更的历史，事务脚本只记最后状态，见<a href="/hello-design-patterns/other/event-sourcing">事件溯源</a>。</li></ul><p>判断线：数一下同一条规则在几个脚本里出现。一次是脚本，两次要警觉，三次该搬进领域对象。</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h2><p>Java：一个退款流程，事务边界在方法上，规则都在函数里。</p><div class="language-java line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">java</span><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E1E4E8;">@</span><span style="color:#F97583;">Service</span></span>
<span class="line"><span style="color:#F97583;">public</span><span style="color:#F97583;"> class</span><span style="color:#B392F0;"> RefundScript</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#F97583;">    private</span><span style="color:#F97583;"> final</span><span style="color:#E1E4E8;"> JdbcTemplate jdbc;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E1E4E8;">    @</span><span style="color:#F97583;">Transactional</span></span>
<span class="line"><span style="color:#F97583;">    public</span><span style="color:#E1E4E8;"> RefundResult </span><span style="color:#B392F0;">refund</span><span style="color:#E1E4E8;">(</span><span style="color:#F97583;">long</span><span style="color:#FFAB70;"> orderId</span><span style="color:#E1E4E8;">, </span><span style="color:#F97583;">long</span><span style="color:#FFAB70;"> amount</span><span style="color:#E1E4E8;">) {</span></span>
<span class="line"><span style="color:#E1E4E8;">        Map&lt;</span><span style="color:#F97583;">String</span><span style="color:#E1E4E8;">, </span><span style="color:#F97583;">Object</span><span style="color:#E1E4E8;">&gt; order </span><span style="color:#F97583;">=</span><span style="color:#E1E4E8;"> jdbc.</span><span style="color:#B392F0;">queryForMap</span><span style="color:#E1E4E8;">(</span></span>
<span class="line"><span style="color:#9ECBFF;">                &quot;SELECT status, paid_amount FROM orders WHERE id = ?&quot;</span><span style="color:#E1E4E8;">, orderId);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">        if</span><span style="color:#E1E4E8;"> (</span><span style="color:#F97583;">!</span><span style="color:#9ECBFF;">&quot;PAID&quot;</span><span style="color:#E1E4E8;">.</span><span style="color:#B392F0;">equals</span><span style="color:#E1E4E8;">(order.</span><span style="color:#B392F0;">get</span><span style="color:#E1E4E8;">(</span><span style="color:#9ECBFF;">&quot;status&quot;</span><span style="color:#E1E4E8;">))) {</span></span>
<span class="line"><span style="color:#F97583;">            throw</span><span style="color:#F97583;"> new</span><span style="color:#B392F0;"> IllegalStateException</span><span style="color:#E1E4E8;">(</span><span style="color:#9ECBFF;">&quot;只有已支付订单能退款&quot;</span><span style="color:#E1E4E8;">);</span></span>
<span class="line"><span style="color:#E1E4E8;">        }</span></span>
<span class="line"><span style="color:#F97583;">        long</span><span style="color:#E1E4E8;"> paid </span><span style="color:#F97583;">=</span><span style="color:#E1E4E8;"> (Long) order.</span><span style="color:#B392F0;">get</span><span style="color:#E1E4E8;">(</span><span style="color:#9ECBFF;">&quot;paid_amount&quot;</span><span style="color:#E1E4E8;">);</span></span>
<span class="line"><span style="color:#F97583;">        if</span><span style="color:#E1E4E8;"> (amount </span><span style="color:#F97583;">&lt;=</span><span style="color:#79B8FF;"> 0</span><span style="color:#F97583;"> ||</span><span style="color:#E1E4E8;"> amount </span><span style="color:#F97583;">&gt;</span><span style="color:#E1E4E8;"> paid) {          </span><span style="color:#818e99;">// 规则一：金额边界</span></span>
<span class="line"><span style="color:#F97583;">            throw</span><span style="color:#F97583;"> new</span><span style="color:#B392F0;"> IllegalArgumentException</span><span style="color:#E1E4E8;">(</span><span style="color:#9ECBFF;">&quot;退款金额非法&quot;</span><span style="color:#E1E4E8;">);</span></span>
<span class="line"><span style="color:#E1E4E8;">        }</span></span>
<span class="line"><span style="color:#E1E4E8;">        jdbc.</span><span style="color:#B392F0;">update</span><span style="color:#E1E4E8;">(</span><span style="color:#9ECBFF;">&quot;UPDATE orders SET status = &#39;REFUNDED&#39;, paid_amount = paid_amount - ? WHERE id = ?&quot;</span><span style="color:#E1E4E8;">,</span></span>
<span class="line"><span style="color:#E1E4E8;">                amount, orderId);                    </span><span style="color:#818e99;">// 规则二：状态与金额一起改</span></span>
<span class="line"><span style="color:#E1E4E8;">        jdbc.</span><span style="color:#B392F0;">update</span><span style="color:#E1E4E8;">(</span><span style="color:#9ECBFF;">&quot;INSERT INTO refund_events (order_id, amount) VALUES (?, ?)&quot;</span><span style="color:#E1E4E8;">,</span></span>
<span class="line"><span style="color:#E1E4E8;">                orderId, amount);</span></span>
<span class="line"><span style="color:#F97583;">        return</span><span style="color:#F97583;"> new</span><span style="color:#B392F0;"> RefundResult</span><span style="color:#E1E4E8;">(orderId, paid </span><span style="color:#F97583;">-</span><span style="color:#E1E4E8;"> amount);</span></span>
<span class="line"><span style="color:#E1E4E8;">    }</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br></div></div><p>对比富领域对象的写法：规则进 <code>Order.refund(amount)</code>，脚本退成&quot;取对象 → 调方法 → 存回&quot;，见<a href="/hello-design-patterns/anti-patterns/anemic-domain-model">贫血模型</a>的改造示例。两种都能跑，区别在规则出现在哪里、被几处共用。</p><h2 id="与相关条目的关系" tabindex="-1">与相关条目的关系 <a class="header-anchor" href="#与相关条目的关系" aria-label="Permalink to “与相关条目的关系”">​</a></h2><ul><li><strong>贫血模型是它的对象化外壳</strong>：把脚本搬进服务、把数据放进实体，流程仍然是线性的，只是多了一层搬运 [S26]。</li><li><strong>领域模型是它的替代方案</strong>：当规则数量超过流程步骤数量时切换，切换方式见<a href="/hello-design-patterns/anti-patterns/anemic-domain-model">贫血模型</a>的&quot;走出来的顺序&quot;。</li><li><strong><a href="/hello-design-patterns/behavioral/command">命令模式</a></strong>：脚本函数封装成对象后，撤销、重放、审计都不用改函数体。</li><li><strong><a href="/hello-design-patterns/other/event-sourcing">事件溯源</a></strong>：脚本只提交最终状态，事件溯源把每一步变更记下来，两者对&quot;审计&quot;的强度不同。</li></ul><h2 id="成本" tabindex="-1">成本 <a class="header-anchor" href="#成本" aria-label="Permalink to “成本”">​</a></h2><p>脚本式的账要算清：单个函数几百行之前都划算，超过之后每条规则的查找成本随脚本数平方增长（要在 N 个脚本里搜同一规则）。切换到领域模型的触发点就是这个交叉点，不是代码行数。</p><h2 id="相关篇目" tabindex="-1">相关篇目 <a class="header-anchor" href="#相关篇目" aria-label="Permalink to “相关篇目”">​</a></h2><ul><li><a href="/hello-design-patterns/anti-patterns/anemic-domain-model">贫血模型</a>：同一份流程的两种归置方式。</li><li><a href="/hello-design-patterns/other/orm">ORM</a>：脚本读写数据的映射层。</li><li><a href="/hello-design-patterns/other/mvc">MVC</a>：脚本通常由控制器调用，控制器本身不放规则。</li><li><a href="/hello-design-patterns/concurrency/read-write-lock">事务与并发</a>：脚本的事务边界与行锁、乐观锁的关系。</li><li><a href="/hello-design-patterns/other/event-sourcing">事件溯源</a>：需要变更历史时的另一条路。</li></ul><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to “来源”">​</a></h2><ul><li>[S5] Martin Fowler，《Patterns of Enterprise Application Architecture》，2002，领域逻辑一章。</li><li>[S26] martinfowler.com bliki，Anemic Domain Model。</li></ul>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};